<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div class="space-y-6" x-data="{secret:null}"><header><h1 class="text-3xl font-bold">Ingest RTMP</h1><p class="text-slate-400 mt-1">Publicación RTMP opcional y protegida por balanceador, IP y clave.</p></header><aside class="border border-blue-900 bg-blue-950/30 rounded-xl p-4 text-sm text-blue-200">RTMP queda desactivado por defecto. Cada cambio se sincroniza mediante la API interna firmada; el agente valida y prueba Nginx antes de recargarlo.</aside><section class="grid xl:grid-cols-2 gap-4"><?php foreach($servers as $s):?><article class="bg-slate-900 border <?=$s['config_status']==='failed'?'border-red-800':'border-slate-800'?> rounded-xl p-5"><div class="flex justify-between"><div><h2 class="text-xl font-bold"><?=$e($s['name'])?></h2><p class="text-xs text-slate-500">Pública <?=$e($s['public_ip']?:'—')?> · Privada <?=$e($s['private_ip']?:'—')?></p></div><span class="<?=$s['config_status']==='active'?'text-blue-400':($s['config_status']==='failed'?'text-red-400':'text-slate-400')?>"><?=$e($s['config_status']?:'Sin configurar')?></span></div><form method="post" action="/rtmp" class="space-y-4 mt-5"><?=$csrf->field()?><input type="hidden" name="server_id" value="<?=$s['id']?>"><div class="grid grid-cols-2 gap-3"><label class="bg-slate-800 p-3 rounded"><input type="checkbox" name="enabled" <?=$s['enabled']?'checked':''?>> Habilitar ingest RTMP</label><label>Puerto<input name="port" type="number" min="1024" max="65535" value="<?=$s['port']?:1935?>" class="w-full bg-slate-800 p-2 rounded mt-1"></label></div><label>IP permitidas para publicar<textarea required name="allowed_ips" rows="4" placeholder="203.0.113.10&#10;198.51.100.25" class="w-full bg-slate-800 p-2 rounded mt-1 font-mono"><?=$e($s['allowed_ips']??'')?></textarea><span class="text-xs text-slate-500">Una IP exacta por línea. No se admiten rangos abiertos.</span></label><div class="flex justify-between items-center"><span class="text-xs text-slate-500">Versión <?=$s['applied_version']??0?> / <?=$s['desired_version']??0?></span><button class="bg-blue-700 px-4 py-2 rounded">Guardar y sincronizar</button></div></form><?php if($s['config_id']):?><div class="flex gap-2 mt-3"><button class="bg-slate-700 px-3 py-2 rounded" @click="fetch('/rtmp/reveal',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_csrf=<?=rawurlencode($csrf->token())?>&id=<?=$s['config_id']?>'}).then(r=>r.json()).then(r=>secret=r.error||('URL: '+r.url+'\nStream Key: '+r.stream_key))">Ver datos de ingest</button><form method="post" action="/rtmp/rotate" onsubmit="return confirm('La clave anterior dejará de funcionar después de sincronizar. ¿Rotar?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$s['config_id']?>"><button class="bg-slate-700 px-3 py-2 rounded">Rotar clave</button></form></div><?php endif?><?php if($s['last_error']):?><p class="text-red-400 text-xs mt-3"><?=$e($s['last_error'])?></p><?php endif?></article><?php endforeach?></section><div x-show="secret" x-cloak style="display:none" class="relative bg-black/80 z-50 grid place-items-center p-4"><div @click.outside="secret=null" class="bg-slate-900 border border-blue-900 rounded-xl p-6 max-w-2xl w-full"><h2 class="font-bold">Datos RTMP</h2><code class="block whitespace-pre-wrap break-all bg-black p-4 rounded mt-3" x-text="secret"></code><p class="text-xs text-amber-400 mt-3">La consulta queda registrada en auditoría. No compartas la clave fuera del encoder autorizado.</p><button @click="secret=null" class="bg-blue-700 px-4 py-2 rounded mt-4">Cerrar</button></div></div></div>
